     #skill-cloud .skill::after { content:''; position:absolute; inset:-6px; border-radius:24px; pointer-events:none; }
     #skill-area:hover #skill-cloud .skill, #skill-area.active #skill-cloud .skill { opacity:1; pointer-events:auto; }
