     [data-theme="dark"] .skill-hint { color: rgba(255,255,255,0.85); }
     [data-theme="dark"] #skill-cloud .skill { color: rgba(255,255,255,0.94); }
     [data-theme="light"] #skill-cloud .skill { color: rgba(0,0,0,0.94); }

     /* responsive: smaller screens */
     @media (max-width: 640px) {
       header { flex-direction:column; gap:8px; text-align:center; }
       header span:first-child { font-size:11px; }
