// --- HERO physics-based magnetic force-field ---
function splitToChars(el) {
  var text = el.textContent||''; 
  text = text.replace(/\s+$/,''); 
  el.textContent=''; 
  for(var i=0;i<text.length;i++){ 
    var ch=text[i]; 
    var s=document.createElement('span'); 
    var parity = (i % 2 === 0) ? 'even' : 'odd'; 
    s.className = 'char ' + parity + (ch=== ' ' ? ' space' : ''); 
    s.textContent = ch; 
    s.classList.add('fade-in'); 
    el.appendChild(s); 
  } 
}

document.addEventListener('DOMContentLoaded', function(){
  var hero = document.getElementById('hero'); if(!hero) return;
  splitToChars(hero);
  var chars = Array.prototype.slice.call(hero.querySelectorAll('.char'));

  // initial fade in
  chars.forEach(function(c,i){ 
    var d=(i*0.03+Math.random()*0.04).toFixed(3)+'s'; 
    c.style.transition='opacity 0.6s ease '+d; 
  });
  requestAnimationFrame(function(){ 
    document.querySelectorAll('.fade-in').forEach(function(el){ el.classList.add('visible'); }); 
  });

  // Physics state
  var state = chars.map(function() {
    return { x: 0, y: 0, vx: 0, vy: 0 }; // offset from rest position
  });

  var physics = {
    spring: 0.08,    // spring stiffness
    damping: 0.82,   // velocity damping (friction)
    repel: 120,      // repulsion radius
    force: 8,        // repulsion strength
    cursorX: -9999,
    cursorY: -9999,
    active: false
  };

  var rect = hero.getBoundingClientRect();
  var heroCenterX = rect.left + rect.width / 2;
  var heroCenterY = rect.top + rect.height / 2;

  // Track cursor
  hero.addEventListener('mousemove', function(e) {
    var r = hero.getBoundingClientRect();
    physics.cursorX = e.clientX;
    physics.cursorY = e.clientY;
    physics.active = true;
  });

  hero.addEventListener('mouseleave', function() {
    physics.active = false;
    physics.cursorX = -9999;
    physics.cursorY = -9999;
  });

  // Touch support
  hero.addEventListener('touchmove', function(e) {
    var touch = e.touches[0];
    if (touch) {
      physics.cursorX = touch.clientX;
      physics.cursorY = touch.clientY;
      physics.active = true;
    }
  }, { passive: true });

  hero.addEventListener('touchend', function() {
    physics.active = false;
    physics.cursorX = -9999;
    physics.cursorY = -9999;
  });

  // Cache char rects periodically (they're stable)
  function getCharRects() {
    var heroRect = hero.getBoundingClientRect();
    return chars.map(function(c) {
      var r = c.getBoundingClientRect();
      return {
        x: r.left + r.width/2 - heroRect.left - heroRect.width/2,
        y: r.top + r.height/2 - heroRect.top - heroRect.height/2
      };
    });
  }

  var charOffsets = getCharRects();

  function updatePhysics() {
    var heroRect = hero.getBoundingClientRect();

    for (var i = 0; i < chars.length; i++) {
      var s = state[i];
      var co = charOffsets[i];

      // Spring force toward rest
      s.vx += -physics.spring * s.x;
      s.vy += -physics.spring * s.y;

      // Damping
      s.vx *= physics.damping;
      s.vy *= physics.damping;

      if (physics.active) {
        // Letter center in viewport
        var lx = heroRect.left + heroRect.width/2 + co.x + s.x;
        var ly = heroRect.top + heroRect.height/2 + co.y + s.y;

        var dx = physics.cursorX - lx;
        var dy = physics.cursorY - ly;
        var dist = Math.sqrt(dx*dx + dy*dy);

        if (dist < physics.repel && dist > 0.1) {
          var strength = (physics.repel - dist) / physics.repel;
          var force = physics.force * strength * strength;
          // Normalize direction: push away from cursor
          var nx = -dx / dist;
          var ny = -dy / dist;
          s.vx += nx * force;
          s.vy += ny * force;
        }
      }

      // Update position
      s.x += s.vx;
      s.y += s.vy;

      // Apply transform
      chars[i].style.transform = 'translate(' + s.x.toFixed(1) + 'px, ' + s.y.toFixed(1) + 'px)';
    }

    requestAnimationFrame(updatePhysics);
  }

  // Start animation loop after a delay (let initial render settle)
  setTimeout(function() {
    charOffsets = getCharRects();
    updatePhysics();

    // Recalculate offsets on resize
    window.addEventListener('resize', function() {
      charOffsets = getCharRects();
    });
  }, 100);
});
