document.addEventListener('DOMContentLoaded', function(){
  var hero = document.getElementById('hero'); if(!hero) return;
  splitToChars(hero);
  var chars = Array.prototype.slice.call(hero.querySelectorAll('.char'));

  // Initial fade-in (no transform transition — physics handles that)
  chars.forEach(function(c,i){
    var d=(i*0.03+Math.random()*0.04).toFixed(3)+'s';
    c.style.transition='opacity 0.6s ease '+d+', color 0.12s ease';
  });
  requestAnimationFrame(function(){ document.querySelectorAll('.fade-in').forEach(function(el){ el.classList.add('visible'); }); });

  // Physics state per character
  var state = chars.map(function(){ return {x:0, y:0, vx:0, vy:0}; });
  var phys = {
    spring: 0.055, damping: 0.85,
    repelRadius: 150, repelForce: 14,
    cx: -9999, cy: -9999, active: false
  };

  // Cursor tracking
  hero.addEventListener('mousemove', function(e){
    phys.cx = e.clientX; phys.cy = e.clientY; phys.active = true;
  });
  hero.addEventListener('mouseleave', function(){ phys.active = false; });
  hero.addEventListener('touchmove', function(e){
    var t = e.touches[0]; if(t){ phys.cx = t.clientX; phys.cy = t.clientY; phys.active = true; }
  }, {passive:true});
  hero.addEventListener('touchend', function(){ phys.active = false; });

  // Char offsets from hero center (stable in document flow)
  var offsets = [];
  function calcOffsets(){
    var hr = hero.getBoundingClientRect();
    var hx = hr.left + hr.width/2, hy = hr.top + hr.height/2;
    offsets = chars.map(function(c){
      if(c.classList.contains('space')) return null;
      var r = c.getBoundingClientRect();
      return {dx: r.left + r.width/2 - hx, dy: r.top + r.height/2 - hy};
    });
  }
  calcOffsets();
  window.addEventListener('resize', calcOffsets);

  // Physics tick
  function tick(){
    var hr = hero.getBoundingClientRect();
    var hx = hr.left + hr.width/2, hy = hr.top + hr.height/2;

    for(var i=0;i<chars.length;i++){
      var s = state[i];
      var off = offsets[i];
      if(!off) continue;

      // Spring toward rest
      s.vx += -phys.spring * s.x;
      s.vy += -phys.spring * s.y;
      s.vx *= phys.damping;
      s.vy *= phys.damping;

      // Magnetic repulsion
      if(phys.active){
        var lx = hx + off.dx + s.x, ly = hy + off.dy + s.y;
        var dx = phys.cx - lx, dy = phys.cy - ly;
        var dist = Math.sqrt(dx*dx + dy*dy);
        if(dist < phys.repelRadius && dist > 1){
          var str = (phys.repelRadius - dist) / phys.repelRadius;
          var f = phys.repelForce * str * str;
          s.vx += -(dx/dist) * f;
          s.vy += -(dy/dist) * f;
        }
      }

      s.x += s.vx;
      s.y += s.vy;

      var rot = Math.max(-18, Math.min(18, s.vx * 3));
      chars[i].style.transform = 'translate3d(' + s.x.toFixed(1) + 'px,' + s.y.toFixed(1) + 'px,0) rotate(' + rot.toFixed(1) + 'deg)';
    }

    requestAnimationFrame(tick);
  }

  setTimeout(function(){ calcOffsets(); tick(); }, 120);
});

